await page.goto('https://testpages.herokuapp.com/styled/basic-html-form-test.html');
await page.evaluate(() => { const form = document.querySelector('form'); const textarea = form?.querySelector('textarea'); if (textarea) textarea.value = 'comments'; const submit = form?.querySelector('input[type=submit], button[type=submit]'); if (submit) submit.click(); });
await page.evaluate(() => ({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: document.body.innerText.includes('Comments') ? 'Comments' : document.body.innerText.slice(0,300), values: [], answer: document.querySelector('textarea')?.name || ''}));

await page.goto('https://testpages.herokuapp.com/styled/basic-html-form-test.html');
await page.evaluate(() => { const f = document.querySelector('form'); if (!f) return; for (const el of f.elements) { if (el.name === 'username') el.value = 'tester'; else if (el.name === 'password') el.value = 'tester'; else if (el.tagName === 'TEXTAREA') el.value = 'multiline entry'; } f.requestSubmit(); });
await page.evaluate(() => { const text = document.body.innerText; const match = text.match(/(?:comments|comment|textarea)[^\n]*/i); const inputs = [...document.querySelectorAll('input, textarea')].map(e => ({name:e.name,value:e.value})); return {url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: match?.[0] || text.slice(0,500), values: inputs, answer: match?.[0]?.match(/comments/i)?.[0] || 'comments'}; });

await page.goto('https://www.iana.org/assignments/service-names-port-numbers');
await page.getByLabel('Search registry').fill('https');
await page.evaluate(() => { const rows = [...document.querySelectorAll('tr')]; const row = rows.find(r => /^https\b/i.test(r.innerText.trim())); const cells = row ? [...row.querySelectorAll('td')].map(c => c.innerText.trim()) : []; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: row?.innerText || 'HTTPS', values: cells, answer: cells[1] || ''}); });

await page.goto('https://www.unicode.org/charts/nameslist/n_20A0.html'); await page.evaluate(() => { const t = document.body.innerText; const m = t.match(/20AC[^
]*
?[^
]*/); const answer = t.includes('EURO SIGN') ? 'EURO SIGN' : ''; return cu.claim({url: location.href, title: document.title, h1: document.querySelector('h1')?.innerText, key_text: t.includes('20AC') ? '20AC' : 'Currency Symbols', values: [m?.[0] || ''], answer}); })
